import math
import re
import numpy as np
from wordfreq import word_frequency, top_n_list
from difflib import SequenceMatcher
import statistics

_W = re.compile(r"[a-zA-Z']+")
STOP = set(("a an the and or but if then else of to in on at by for with from as is are was were be been being it its this that these those i you he she we they me him her us them my your his their our not no so do does did have has had will would can could should may might must about into over under out up down off than too very just also").split())

def _toks(s):
    return [t for t in _W.findall((s or "").lower())]

def _content(s):
    return [t for t in _toks(s) if t not in STOP and len(t) > 1]

def _log_freq(word):
    p = word_frequency(word, "en")
    if p > 0:
        return -math.log2(p)
    return 24.0

def _ref_freq_alignment_stats():
    """Reference distribution of log-freq differences between word pairs."""
    words = top_n_list("en", 10000)
    freqs = [-math.log2(word_frequency(w, "en")) for w in words if word_frequency(w, "en") > 0]
    diffs = []
    for i in range(0, min(len(freqs)-1, 1000), 10):
        for j in range(i+1, min(i+20, len(freqs))):
            diffs.append(abs(freqs[i] - freqs[j]))
    mu = statistics.mean(diffs) if diffs else 5.0
    sd = statistics.stdev(diffs) if len(diffs) > 1 else 2.0
    return mu, sd

_FREQ_MU, _FREQ_SD = _ref_freq_alignment_stats()

def replace_token_frequency_alignment(text, anchor):
    """Measure quality of word replacements via frequency alignment."""
    if not (text and anchor):
        return 0.5
    anchor_toks = _content(anchor)
    text_toks = _content(text)
    if not text_toks or not anchor_toks:
        return 0.5

    matcher = SequenceMatcher(None, anchor_toks, text_toks)
    opcodes = matcher.get_opcodes()

    replace_scores = []
    for op, a_start, a_end, b_start, b_end in opcodes:
        if op == "replace" and (a_end - a_start) == (b_end - b_start):
            for i in range(a_end - a_start):
                anchor_tok = anchor_toks[a_start + i]
                text_tok = text_toks[b_start + i]
                f_anchor = _log_freq(anchor_tok)
                f_text = _log_freq(text_tok)
                freq_diff = abs(f_anchor - f_text)

                # Inverted-U: score based on normalized difference
                # Ideal: small-moderate difference (0.5-2 SDs)
                normalized_diff = (freq_diff - _FREQ_MU) / (_FREQ_SD + 0.1)
                if abs(normalized_diff) < 0.5:
                    mod_score = 0.7  # too similar, minimal change
                elif abs(normalized_diff) < 1.5:
                    mod_score = 1.0  # sweet spot
                elif abs(normalized_diff) < 3.0:
                    mod_score = 0.6  # diverging
                else:
                    mod_score = 0.1  # extreme divergence
                replace_scores.append(mod_score)

    if replace_scores:
        return max(0.0, min(1.0, statistics.mean(replace_scores)))
    return 0.5

METRICS = {"replace_token_frequency_alignment": replace_token_frequency_alignment}
